void CityMode::handleCityInput() {
    if (modalActive) {
        if (keyUp) {
            House::handleModalAction(-1);
            clearInputState();
        } else if (keyDown) {
            if (House::handleModalAction(1)) {
                modalActive = false;
                needsRepaint = true;
                CityMode::saveState();
            }
            clearInputState();
        } else if (keyFire) {
            if (House::handleModalAction(0)) {
                modalActive = false;
                needsRepaint = true;
                CityMode::saveState();
            }
            clearInputState();
        }
    } else if (phase == 0) {
        if (launchDelay < 0 && placementResultTimer < 0) {
            if (keyUp) {
                if (selectedBuilding > 0) {
                    selectedBuilding--;
                }
            } else if (keyDown) {
                if (selectedBuilding < 3) {
                    selectedBuilding++;
                }
            } else if (keyFire && ((selectedBuilding <= unlockedBuildingTier && selectedBuilding <= highestTierUnlocked) || cheatActive)) {
                launchDelay = 500;
            }
        }
    } else if (placeDelay < 0 && !placementInProgress && placementResultTimer < 0) {
        if (keyUp) {
            if (cursorCol >= 0 && cursorRow > 0) {
                cursorRow--;
                slideX = 0;
                slideY = 34;
                slideTimer = 150;
            }
        } else if (keyDown) {
            if (cursorRow < 4) {
                cursorRow++;
                slideX = 0;
                slideY = -34;
                slideTimer = 150;
            }
        } else if (keyLeft) {
            if (cursorCol > 0) {
                cursorCol--;
                slideX = 34;
                slideY = 0;
                slideTimer = 150;
            } else if (cursorCol == 0) {
                slideX = ((cursorCol * 34) + 8) + 32;
                slideY = ((cursorRow * 34) + 29) - 161;
                cursorCol--;
                cursorRow = 4;
                slideTimer = 150;
            }
        } else if (keyRight) {
            if (cursorCol < 0) {
                cursorCol++;
                slideX = -32 - ((cursorCol * 34) + 8);
                slideY = 161 - ((cursorRow * 34) + 29);
                slideTimer = 150;
            } else if (cursorCol < 4) {
                cursorCol++;
                slideX = -34;
                slideY = 0;
                slideTimer = 150;
            }
        } else if (keyFire && (cursorCol < 0 || cellLevels[(cursorRow * 5) + cursorCol] >= pieceType - 1 || cheatActive)) {
            placementInProgress = true;
            placeAnimTimer = 3000;
            if (cursorCol >= 0) {
                populationTarget = population;
                population -= grid[(((cursorRow * 5) + cursorCol) * 3) + 1];
                population += pieceValue;
                populationPending = populationTarget - population;
                digitSheetCurrent = digitSheetA;
                int maxHintWidth = GameMIDlet::screenWidth - 20;
                String message;
                if (population > populationTarget) {
                    message = Resources::getString(67, Arr<String>( { String::valueOf(population - populationTarget) }));
                    } else if (population < populationTarget) {
                        message = Resources::getString(69, Arr<String>( { String::valueOf(populationTarget - population) }));
                        digitSheetCurrent = digitSheetB;
                        } else {
                            message = Resources::getString(68);
                        }
                        hintCustom = House::wrapText(message, font, maxHintWidth);
                        if (population / 10000 != populationTarget / 10000) {
                            populationFlashCount = 5;
                        } else if (population / 1000 != populationTarget / 1000) {
                            populationFlashCount = 4;
                        } else if (population / 100 != populationTarget / 100) {
                            populationFlashCount = 3;
                        } else if (population / 10 != populationTarget / 10) {
                            populationFlashCount = 2;
                        } else if (population != populationTarget) {
                            populationFlashCount = 1;
                        } else {
                            populationFlashCount = 0;
                        }
                        if (populationFlashCount > 0) {
                            populationFlashTimer = 300;
                        }
                        int cellIndex = (((cursorRow * 5) + cursorCol) * 3) + 0;
                        targetCellEmpty = (grid[cellIndex] == 0);
                        grid[cellIndex] = 0;
                    }
                }
            }
            clearInputState();
}

void CityMode::updateCityHintText(int totalTimeMs) {
    if (helpLines == null) {
        helpLines = Arr<Arr<String>>::sized(12);
    }
    Arr<String> nextHint;
    if (phase == 0) {
        nextHint = (selectedBuilding <= unlockedSpecialTier) ? helpLines[selectedBuilding + 4]: (selectedBuilding <= unlockedBuildingTier) ? helpLines[selectedBuilding]: helpLines[selectedBuilding + 8];
    } else {
        if (hintCustom == null) {
            int maxHintWidth = GameMIDlet::screenWidth - 20;
            String message;
            if (population > populationTarget) {
                message = Resources::getString(67, Arr<String>( { String::valueOf(population - populationTarget) }));
                } else if (population < populationTarget) {
                    message = Resources::getString(69, Arr<String>( { String::valueOf(populationTarget - population) }));
                    digitSheetCurrent = digitSheetB;
                    } else {
                        message = Resources::getString(68);
                    }
                    hintCustom = House::wrapText(message, font, maxHintWidth);
                }
                nextHint = (cursorCol < 0) ? hintOffGrid: (placementInProgress || placementResultTimer >= 0) ? hintCustom: (cellLevels[(cursorRow * 5) + cursorCol] < pieceType - 1) ? hintCellTooLow: hintPlaceable;
            }
            Arr<String> prevHint = hintLines;
            hintLines = nextHint;
            hintScrollTimer -= totalTimeMs;
            if (hintLines != prevHint) {
                hintScrollTimer = 2000;
                hintScroll = 0;
            }
            if (hintScrollTimer < 0 && hintLines.length > hintLinesVisible) {
                hintScrollTimer = 2000;
                hintScroll += hintLinesVisible;
                if (hintScroll >= hintLines.length + hintLinesVisible) {
                    hintScroll = 0;
                }
            }
}

int CityMode::mapGameAction(int keyCode, int gameAction) {
    if (keyCode == 50) {
        return 0;
    }
    if (keyCode == 56) {
        return 1;
    }
    if (keyCode == 52) {
        return 2;
    }
    if (keyCode == 54) {
        return 3;
    }
    if (keyCode != 53) {
        if (gameAction == 1) {
            return 0;
        }
        if (gameAction == 6) {
            return 1;
        }
        if (gameAction == 2) {
            return 2;
        }
        if (gameAction == 5) {
            return 3;
        }
        if (gameAction != 8) {
            return -1;
        }
    }
    return 5;
}

